func (c *TypedScope) GetTypeThroughNamespace(moduleId string) jstype.JSType {
	split := moduleId.LastIndexOf('.')
	if split >= 0 {
		parentName := moduleId.Substring(0, split)
		prop := moduleId.Substring(split + 1)
		parentType := GetTypeThroughNamespace(parentName)
		if parentType == nil || parentType.ToMaybeObjectType() == nil {
